#!/usr/bin/env node
/**
 * Bundle compile_staff_order_draft + sync_order_draft_from_odoo for Kapso (sin import/fs).
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");
const fnDir = path.join(root, "functions");

function stripModuleSyntax(src) {
  return src
    .replace(/^import[\s\S]*?from\s+["'][^"']+["'];\s*\n/gm, "")
    .replace(/^import\s+["'][^"']+["'];\s*\n/gm, "")
    .replace(/^export \{[^}]*\};?\s*\n?/gm, "")
    .replace(/^export /gm, "");
}

function braceDelta(line) {
  let delta = 0;
  for (const ch of line) {
    if (ch === "{") delta++;
    else if (ch === "}") delta -= 1;
  }
  return delta;
}

function dropDuplicateFunctions(src, declared) {
  const lines = src.split("\n");
  const out = [];
  let skipping = false;
  let skipDepth = 0;
  for (const line of lines) {
    if (skipping) {
      skipDepth += braceDelta(line);
      if (skipDepth <= 0) skipping = false;
      continue;
    }
    const fnMatch = line.match(/^(async )?function (\w+)\s*\(/);
    if (fnMatch) {
      const name = fnMatch[2];
      if (declared.has(name)) {
        skipping = true;
        skipDepth = braceDelta(line);
        if (skipDepth <= 0 && line.includes("}")) skipping = false;
        continue;
      }
      declared.add(name);
    }
    out.push(line);
  }
  return out.join("\n");
}

/** Strip `const CATALOG_CACHE = {…};` even when the object is a single huge line. */
function stripCatalogCacheConst(src) {
  const marker = "const CATALOG_CACHE = ";
  const start = src.indexOf(marker);
  if (start < 0) return src;
  const braceStart = src.indexOf("{", start);
  if (braceStart < 0) return src;
  let depth = 0;
  for (let j = braceStart; j < src.length; j++) {
    const ch = src[j];
    if (ch === "{") depth++;
    else if (ch === "}") {
      depth--;
      if (depth === 0) {
        let end = j + 1;
        if (src[end] === ";") end++;
        while (end < src.length && /[\s\n]/.test(src[end])) end++;
        return src.slice(0, start) + src.slice(end);
      }
    }
  }
  return src;
}

// --- compile bundle ---
{
  const catalog = JSON.parse(fs.readFileSync(path.join(root, "catalog_cache.json"), "utf8"));
  const declared = new Set();
  const parts = [];
  parts.push(`const CATALOG_CACHE = ${JSON.stringify(catalog)};\n`);
  parts.push(`function loadCatalog() { return CATALOG_CACHE; }\n`);
  parts.push(`function loadSemantic() { return null; }\n`);
  parts.push(`function buildCatalogForMatch() {
  const cache = loadCatalog();
  return { products: cache.products || [], synced_at: cache.synced_at || null };
}\n`);

  for (const rel of [
    "lib/commercial_policy.js",
    "lib/product_match_engine.js",
    "lib/staff_order_contract.js",
  ]) {
    let raw = stripModuleSyntax(fs.readFileSync(path.join(fnDir, rel), "utf8"));
    parts.push(dropDuplicateFunctions(raw, declared));
  }

  let handler = stripModuleSyntax(
    fs.readFileSync(path.join(fnDir, "compile_staff_order_draft.js"), "utf8")
  );
  // Remove local loadCatalog/loadSemantic/buildCatalogForMatch and Node-only leftovers
  // + duplicate CATALOG_CACHE (bundle already injects catalog_cache.json at top)
  handler = stripCatalogCacheConst(handler)
    .replace(/function loadCatalog\([\s\S]*?\n\}\n/, "")
    .replace(/function loadSemantic\([\s\S]*?\n\}\n/, "")
    .replace(/function buildCatalogForMatch\([\s\S]*?\n\}\n/, "")
    .replace(/const __dirname[\s\S]*?;\n/g, "")
    .replace(/.*fileURLToPath\(import\.meta\.url\).*\n/g, "")
    .replace(/.*import\.meta\.url.*\n/g, "")
    .replace(/import \{ readFileSync \} from "fs";\n/g, "")
    .replace(/import \{ fileURLToPath \} from "url";\n/g, "")
    .replace(/import path from "path";\n/g, "");
  // Also drop duplicate isDesignExplorationOrder if isDesignExploration already from staff_order_contract
  handler = handler.replace(
    /\/\*\* Excepción mín\. 6: solo diseño \/ muestra \(explícito\)\. \*\/\nfunction isDesignExplorationOrder\([\s\S]*?\n\}\n/,
    ""
  );
  // Point local evaluate (if kept) at isDesignExploration
  handler = handler.replace(/isDesignExplorationOrder\(/g, "isDesignExploration(");
  parts.push(dropDuplicateFunctions(handler, declared));

  const out = path.join(fnDir, "compile_staff_order_draft_deploy.js");
  fs.writeFileSync(out, `// AUTO-GENERATED by bundle_staff_complete_order.js\n${parts.join("\n\n")}\n`);
  console.log("Wrote", out, fs.statSync(out).size, "bytes");
}

// --- sync bundle ---
{
  const declared = new Set();
  const parts = [];
  for (const rel of [
    "lib/staff_order_contract.js",
    "lib/sale_order_spreadsheet.js",
    "lib/sync_order_draft_from_odoo.js",
  ]) {
    parts.push(
      dropDuplicateFunctions(
        stripModuleSyntax(fs.readFileSync(path.join(fnDir, rel), "utf8")),
        declared
      )
    );
  }
  parts.push(
    dropDuplicateFunctions(
      stripModuleSyntax(fs.readFileSync(path.join(fnDir, "sync_order_draft_from_odoo.js"), "utf8")),
      declared
    )
  );
  const out = path.join(fnDir, "sync_order_draft_from_odoo_deploy.js");
  fs.writeFileSync(out, `// AUTO-GENERATED by bundle_staff_complete_order.js\n${parts.join("\n\n")}\n`);
  console.log("Wrote", out, fs.statSync(out).size, "bytes");
}
